import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

ENTRY_NAME = "conv2d_kernel"

# ---------------------------------------------------------------------------
# Hand written PTX implementing the same direct 3x3 convolution semantics as
# the reference CuTe/CUDA kernel:
#   X : [N, IC=3, H, Win]      bf16, contiguous
#   W : [OC=32, IC=3, KH=3, KW=3]  bf16, contiguous
#   Y : [N, OC=32, Hout, Wout] bf16, contiguous  (Hout = H-2, Wout = Win-2)
#
# Grid:  (ceil(Wout/16), ceil(Hout/16), N)
# Block: (16, 16, 1)
#
# Optimization applied (structural rewrite): in addition to staging the
# weight tensor into shared memory, the input activation tile (16x16 output
# tile + 2-pixel halo on each side = 18x18 per input channel, for all 3
# input channels) is cooperatively loaded into shared memory once per CTA.
# All 256 threads in the CTA then reuse this staged tile directly out of
# shared memory for all 32 output channels, eliminating the large amount of
# redundant global-memory re-reads that neighboring output pixels previously
# performed (each interior input pixel is read up to 9 times by different
# threads under the 3x3 sliding window).
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64
// ---------------------------------------------------------------------------
// Direct 3x3 convolution kernel with cooperative shared-memory staging of both
// the weight tensor and the halo'd input activation tile (as in the previous
// version), PLUS a register-blocking optimization: each thread now computes
// TWO output pixels (spaced 16 columns apart, i.e. a 32-wide output tile per
// CTA instead of 16-wide) across all 32 output channels. Each weight value is
// loaded from shared memory once per (oc,k) and reused via FMA for both output
// columns, halving the number of shared-memory weight loads and instruction
// count relative to computing one output pixel per thread, while keeping the
// same 16x16 (256-thread) CTA and the same cooperative staging structure.
// ---------------------------------------------------------------------------
