    // Profiling showed 72 regs/thread limiting theoretical occupancy to
    // 50% (3 of 6 possible CTAs/SM resident). Hinting the compiler to
    // target 4 CTAs/SM per scheduler forces a lower register allocation,
    // raising achieved occupancy without altering kernel semantics.
    .minnctapersm 4
{
    .reg .pred %p<20>;
    .reg .b16  %rs<12>;
    .reg .f32  %f<9>;
    .reg .b32 %r<160>;
    .reg .b64  %rd<20>;
    .shared .align 2 .b8 sW[1728];
    .shared .align 2 .b8 sX[3672];
    ld.param.u64 %rd1, [conv2d_kernel_param_0];   // X
    ld.param.u64 %rd2, [conv2d_kernel_param_1];   // W
    ld.param.u64 %rd3, [conv2d_kernel_param_2];   // Y
    ld.param.u32 %r1,  [conv2d_kernel_param_4];   // H
    ld.param.u32 %r2,  [conv2d_kernel_param_5];   // Win
    ld.param.u32 %r3,  [conv2d_kernel_param_6];   // Hout
    ld.param.u32 %r4,  [conv2d_kernel_param_7];   // Wout
