    mov.u32 %r6, %tid.y;             // ty
    mov.u32 %r7, %ctaid.x;
    mov.u32 %r8, %ctaid.y;
    mov.u32 %r9, %ctaid.z;           // n (batch index)
    mad.lo.s32 %r10, %r6, 16, %r5;   // tid = ty*16 + tx
