$load_w_loop:
    setp.ge.s32 %p1, %r13, 864;
    @%p1 bra $load_w_done;
    mul.wide.s32 %rd7, %r13, 2;
    add.s64 %rd8, %rd5, %rd7;
    ld.global.u16 %rs1, [%rd8];
