class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.in_channels = 3
        self.out_channels = 32
        self.kernel_size = (3, 3)

        self.weight = nn.Parameter(
            torch.empty(
                self.out_channels,
                self.in_channels,
                self.kernel_size[0],
                self.kernel_size[1],
                dtype=torch.bfloat16,
            )
        )
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

        self._module = None

    def _get_module(self):
        if self._module is None:
            self._module = PtxModule(PTX_SOURCE)
            # ensure the entry exists / is compiled/lookup-able
            self._module.function(ENTRY_NAME)
        return self._module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "input must be CUDA"
        assert x.dtype == torch.bfloat16, "input must be bfloat16"

        x_c = x.contiguous()
        w_c = self.weight.contiguous()

        N = int(x_c.shape[0])
        C = int(x_c.shape[1])
        H = int(x_c.shape[2])
        Win = int(x_c.shape[3])

        OC = int(w_c.shape[0])
        IC = int(w_c.shape[1])
        KH = int(w_c.shape[2])
        KW = int(w_c.shape[3])

        assert C == IC
        assert IC == 3 and OC == 32 and KH == 3 and KW == 3, \
            "kernel specialized for IC=3, OC=32, K=3x3"

        Hout = H - KH + 1
        Wout = Win - KW + 1
        assert Hout > 0 and Wout > 0

        y = torch.empty((N, OC, Hout, Wout), dtype=torch.bfloat16, device=x.device)

        module = self._get_module()

        TILE_H = 16
        BLOCK_W = 16
        OUT_TILE_W = 32  # each thread computes 2 output columns (register blocking)
        grid = ((Wout + OUT_TILE_W - 1) // OUT_TILE_W,
                (Hout + TILE_H - 1) // TILE_H,
                N)
        block = (BLOCK_W, TILE_H, 1)

        stream = torch.cuda.current_stream(device=x.device)

        args = [
            u64(x_c.data_ptr()),
            u64(w_c.data_ptr()),
            u64(y.data_ptr()),
            i32(N),
            i32(H),
            i32(Win),
            i32(Hout),
            i32(Wout),
        ]

        module.launch(
            ENTRY_NAME,
            grid,
            block,
            args,
            stream=stream,
        )

        return y

